<?php
session_start();
if (empty($_SESSION['User_id']) || strtolower((string)($_SESSION['User_role'] ?? '')) !== 'official') { header('Location: login.php'); exit; }
require_once __DIR__ . '/../config/dashboard.php';
$uid=(int)$_SESSION['User_id'];
$stmt=$conn->prepare('SELECT fname,lname,email,phone,address FROM users WHERE ID=?');$stmt->bind_param('i',$uid);$stmt->execute();$user=$stmt->get_result()->fetch_assoc()?:[];
$reports=$conn->query("SELECT wr.*,u.fname,u.lname FROM waste_reports wr JOIN users u ON u.ID=wr.user_id ORDER BY FIELD(wr.status,'pending','verified','resolved','rejected'),wr.created_at DESC")->fetch_all(MYSQLI_ASSOC);
$observations=$conn->query("SELECT o.*,c.fname collector_fname,c.lname collector_lname,r.fname resident_fname,r.lname resident_lname FROM segregation_observations o JOIN users c ON c.ID=o.collector_id JOIN users r ON r.ID=o.resident_id ORDER BY FIELD(o.status,'pending','approved','rejected'),o.created_at DESC")->fetch_all(MYSQLI_ASSOC);
$claims=$conn->query("SELECT rc.claim_id,rc.points_spent,rc.status,rc.claimed_at,u.fname,u.lname,r.reward_name FROM reward_claims rc JOIN users u ON u.ID=rc.user_id JOIN rewards r ON r.reward_id=rc.reward_id ORDER BY FIELD(rc.status,'pending','claimed','cancelled'),rc.claimed_at DESC")->fetch_all(MYSQLI_ASSOC);
$schedules=$conn->query("SELECT cs.*,u.fname,u.lname FROM collection_schedules cs LEFT JOIN users u ON u.ID=cs.collector_id ORDER BY cs.schedule_date DESC,cs.start_time DESC LIMIT 100")->fetch_all(MYSQLI_ASSOC);
$collectors=$conn->query("SELECT ID,fname,lname FROM users WHERE LOWER(role)='collector' AND LOWER(status)='active' ORDER BY fname,lname")->fetch_all(MYSQLI_ASSOC);
$stats=$conn->query("SELECT SUM(status='pending') pending,SUM(status='verified') verified,SUM(status='resolved') resolved FROM waste_reports")->fetch_assoc();
$pendingClaims=(int)$conn->query("SELECT COUNT(*) c FROM reward_claims WHERE status='pending'")->fetch_assoc()['c'];
$notice=dashboard_notice();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Official workspace – BarangayEcoCare</title><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700&display=swap"><link rel="stylesheet" href="../style/global.css"><link rel="stylesheet" href="../style/dashboard.css"></head><body>
<div class="shell"><aside class="sidebar"><div><a href="../index.php" class="logo">Barangay<b>EcoCare</b></a><p class="ws">Official workspace</p></div><nav class="nav"><a href="#v1">Overview</a><a href="#v2">Reports</a><a href="#v3">Schedules</a><a href="#v4">Redemptions</a><a href="#v5">Profile</a><a href="#v6">Segregation</a></nav><div class="me"><div class="me-info"><span class="avatar"><?=e(strtoupper(substr($user['fname']??'O',0,1)))?></span><div><?=e(($user['fname']??'').' '.($user['lname']??''))?><small>Barangay Official</small></div></div><a href="logout.php" class="btn">Log out</a></div></aside><main class="main"><div class="views"><?php if($notice):?><p class="notice" role="status"><?=e($notice)?></p><?php endif;?>
<section class="view" id="v1"><h1>Welcome, <?=e($user['fname']??'')?></h1><p class="sub">Barangay operations overview.</p><div class="grid g4"><article class="card stat"><small>Reports to review</small><b><?= (int)($stats['pending']??0)?></b></article><article class="card stat"><small>Verified</small><b><?= (int)($stats['verified']??0)?></b></article><article class="card stat"><small>Resolved</small><b><?= (int)($stats['resolved']??0)?></b></article><article class="card stat"><small>Pending redemptions</small><b><?= $pendingClaims?></b></article></div><article class="card" style="margin-top:var(--gap)"><h2>Needs attention</h2><p><?= (int)($stats['pending']??0)?> reports and <?=$pendingClaims?> reward requests are awaiting review.</p><a href="#v2" class="btn btn-primary">Review reports</a></article></section>
<section class="view" id="v2"><h1>Waste reports</h1><p class="sub">Review reports and update their status. Award points only when a report is verified.</p><article class="card"><ul class="rows"><?php if(!$reports):?><li><span class="muted">No reports have been submitted.</span></li><?php else:foreach($reports as $r):?><li><div><strong><?=e($r['category'])?> · <?=e($r['location_details'])?></strong><small>By <?=e($r['fname'].' '.$r['lname'])?> · <?=e(date('M j, Y g:i A',strtotime($r['created_at'])))?></small><small><?=nl2br(e($r['description']))?></small><?php if($r['photo_path']):?><small><a href="../<?=e($r['photo_path'])?>" target="_blank" rel="noopener">View photo evidence</a></small><?php endif;?></div><form action="dashboard-action.php" method="post" class="acts"><?php dashboard_form_token();?><input type="hidden" name="action" value="report_status"><input type="hidden" name="section" value="v2"><input type="hidden" name="report_id" value="<?=(int)$r['report_id']?>"><select name="status" aria-label="Report status"><option value="verified" <?=$r['status']==='verified'?'selected':''?>>Verified</option><option value="resolved" <?=$r['status']==='resolved'?'selected':''?>>Resolved</option><option value="rejected" <?=$r['status']==='rejected'?'selected':''?>>Rejected</option></select><input type="number" name="points" min="0" max="1000" value="0" aria-label="Points to award" style="width:90px"><button class="btn btn-primary btn-sm">Save</button><small><?=e(ucfirst($r['status']))?></small></form></li><?php endforeach;endif;?></ul></article></section>
<section class="view" id="v3"><h1>Collection schedules</h1><p class="sub">Create dated collection routes and assign active collectors.</p><form class="card grid g3" action="dashboard-action.php" method="post"><?php dashboard_form_token();?><input type="hidden" name="action" value="create_schedule"><input type="hidden" name="section" value="v3"><label class="field"><span>Area / purok</span><input name="area_purok" required placeholder="Purok 1–3"></label><label class="field"><span>Date</span><input type="date" name="schedule_date" min="<?=date('Y-m-d')?>" required></label><label class="field"><span>Waste type</span><input name="waste_type" required placeholder="General waste"></label><label class="field"><span>Start time</span><input type="time" name="start_time"></label><label class="field"><span>End time</span><input type="time" name="end_time"></label><label class="field"><span>Collector</span><select name="collector_id"><option value="">Unassigned</option><?php foreach($collectors as $c):?><option value="<?=(int)$c['ID']?>"><?=e($c['fname'].' '.$c['lname'])?></option><?php endforeach;?></select></label><button class="btn btn-primary">Create schedule</button></form><article class="card" style="margin-top:var(--gap)"><h2>Posted schedules</h2><ul class="rows"><?php if(!$schedules):?><li><span class="muted">No collection schedules have been posted.</span></li><?php else:foreach($schedules as $s):?><li><div><strong><?=e($s['area_purok'])?> · <?=e($s['waste_type'])?></strong><small><?=e(date('D, M j, Y',strtotime($s['schedule_date'])))?> · <?=e($s['start_time']?date('g:i A',strtotime($s['start_time'])):'Time not set')?><?= $s['fname']?' · '.e($s['fname'].' '.$s['lname']):' · Unassigned'?></small></div><span class="badge b-pending"><?=e(ucwords(str_replace('_',' ',$s['status'])))?></span></li><?php endforeach;endif;?></ul></article></section>
<section class="view" id="v4"><h1>Reward redemptions</h1><p class="sub">Points are reserved when the resident submits a request. Cancelling returns points and stock.</p><article class="card"><ul class="rows"><?php if(!$claims):?><li><span class="muted">No reward claims.</span></li><?php else:foreach($claims as $c):?><li><div><strong><?=e($c['reward_name'])?> · <?=e($c['fname'].' '.$c['lname'])?></strong><small><?=number_format((int)$c['points_spent'])?> points · <?=e(date('M j, Y',strtotime($c['claimed_at'])))?></small></div><?php if($c['status']==='pending'):?><form action="dashboard-action.php" method="post" class="acts"><?php dashboard_form_token();?><input type="hidden" name="action" value="claim_status"><input type="hidden" name="section" value="v4"><input type="hidden" name="claim_id" value="<?=(int)$c['claim_id']?>"><button name="status" value="claimed" class="btn btn-primary btn-sm">Approve</button><button name="status" value="cancelled" class="btn btn-sm">Cancel and refund</button></form><?php else:?><span class="badge b-pending"><?=e(ucfirst($c['status']))?></span><?php endif;?></li><?php endforeach;endif;?></ul></article></section>
<section class="view" id="v5"><h1>My profile</h1><div class="grid g2"><form class="card" action="dashboard-action.php" method="post"><?php dashboard_form_token();?><input type="hidden" name="action" value="update_profile"><input type="hidden" name="section" value="v5"><?php foreach(['fname'=>'First name','lname'=>'Last name','email'=>'Email','phone'=>'Phone','address'=>'Address'] as $key=>$label):?><label class="field"><span><?=e($label)?></span><input name="<?=e($key)?>" value="<?=e($user[$key]??'')?>" <?=$key==='email'?'type="email" required':''?> <?=$key==='fname'||$key==='lname'?'required':''?>></label><?php endforeach;?><button class="btn btn-primary">Save profile</button></form><form class="card" action="dashboard-action.php" method="post"><?php dashboard_form_token();?><input type="hidden" name="action" value="change_password"><input type="hidden" name="section" value="v5"><label class="field"><span>New password</span><input type="password" name="password" minlength="8" required></label><label class="field"><span>Confirm password</span><input type="password" name="confirm" minlength="8" required></label><button class="btn btn-primary">Change password</button></form></div></section>
<section class="view" id="v6"><h1>Segregation observations</h1><p class="sub">Review collector evidence and award points to the resident.</p><article class="card"><ul class="rows"><?php if(!$observations):?><li><span class="muted">No observations submitted.</span></li><?php else:foreach($observations as $o):?><li><div><strong><?=e($o['area_purok'])?> · <?=e($o['location_details'])?></strong><small><?=e($o['proper_bins'])?> of <?=e($o['total_bins'])?> bins sorted · Resident <?=e($o['resident_fname'].' '.$o['resident_lname'])?> · Collector <?=e($o['collector_fname'].' '.$o['collector_lname'])?></small><small><?=nl2br(e($o['notes']))?></small><?php if($o['photo_path']):?><small><a href="../<?=e($o['photo_path'])?>" target="_blank" rel="noopener">View photo evidence</a></small><?php endif;?></div><?php if($o['status']==='pending'):?><form action="dashboard-action.php" method="post" class="acts"><?php dashboard_form_token();?><input type="hidden" name="action" value="observation_status"><input type="hidden" name="section" value="v6"><input type="hidden" name="observation_id" value="<?=(int)$o['observation_id']?>"><input type="number" name="points" min="0" max="1000" value="50" aria-label="Award points"><button class="btn btn-primary btn-sm" name="status" value="approved">Approve</button><button class="btn btn-sm" name="status" value="rejected">Reject</button></form><?php else:?><span class="badge b-pending"><?=e(ucfirst($o['status']))?></span><?php endif;?></li><?php endforeach;endif;?></ul></article></section>
</div></main></div></body></html>
